#[derive(Clone, Copy)]
struct Pointer {
    local: u32,
    offset: u32,
}

#[derive(Clone)]
enum Value {
    /// Emitter control completion only; no local, ABI or runtime value exists.
    Bottom,
    Scalar {
        local: u32,
        ty: ResolvedType,
    },
    ScalarMemory {
        pointer: Pointer,
        ty: ResolvedType,
    },
    Aggregate {
        pointer: Pointer,
