        write_u32(self.output, destination);
        self.get_scalar(left);
        self.get_scalar(right);
        self.output.push(0x85);
        self.get_scalar(left);
        self.output.push(0x20);
        write_u32(self.output, destination);
        self.output.push(0x85);
