    + std::mem::size_of::<hir::ResolvedVariantCaseDeclaration>()
    + std::mem::size_of::<hir::ResolvedFieldDeclaration>()
    + std::mem::size_of::<hir::ResolvedInterface>()
    + std::mem::size_of::<hir::ResolvedImport>();
